handler_source.onChange:
{(e) => {
            setPermission(e.target.checked);
            if (!e.target.checked) {
              ticket.current++;
              if (objectUrl.current) URL.revokeObjectURL(objectUrl.current);
              objectUrl.current = null;
              setAttachment(null);
            }
          }}

{async (e) => {
            const file = e.target.files?.[0];
            e.target.value = "";
            if (!file) return;
            const id = ++ticket.current;
            if (
              !permission ||
              ![
                "image/jpeg",
                "image/png",
                "image/webp",
                "application/pdf",
              ].includes(file.type) ||
              file.size > 10 * 1024 * 1024
            ) {
              setFileError("Choose a JPEG, PNG, WebP or PDF under 10 MB.");
              return;
            }
            const url = URL.createObjectURL(file);
            try {
              if (file.type !== "application/pdf") {
                const img = new Image();
                img.src = url;
                await img.decode();
                if (img.naturalWidth * img.naturalHeight > 40000000)
                  throw Error();
              }
              if (ticket.current !== id) {
                URL.revokeObjectURL(url);
                return;
              }
              if (objectUrl.current) URL.revokeObjectURL(objectUrl.current);
              objectUrl.current = url;
              setAttachment({
                name: file.name,
                url,
                image: file.type !== "application/pdf",
              });
              setFileError("");
            } catch {
              URL.revokeObjectURL(url);
              if (ticket.current === id)
                setFileError(
                  "This file could not be previewed safely. Choose another.",
                );
            }
          }}

